
const pegs=["Aro", "Tea", "Noé", "Humo", "Oca", "Ola", "Oso", "Ufo", "Hacha", "Ave", "Toro", "Teta, dado, tata", "Tina, duna, tuna", "Átomo", "Taco", "Tela", "Tos, taza", "Tufo, taifa", "Techo, teja, toga, daga", "Tubo, tapa, tuba", "Noria", "Nata, nido", "Niño", "Nemo (el pececito)", "Nuca, anca", "Nilo (entre las pirámides)", "Anís (anisetes de colores)", "Nife (centro de la Tierra y lava volcánica)", "Nicho", "Nube, nabo", "Meru (tu perra blanca y negra)", "Moto, mata, meta", "Mina, mono (King Kong)", "Momia, memo, mamá", "Hamaca, moco", "Mula, miel", "Mesa, maza", "Mafia (gánster con traje a rayas)", "Mecha, macho, mago", "Mopa, ameba", "Coro, car (mini car)", "Cohete, coto", "Cuna, cuña, cono", "Cama", "Coco, coque (carbón)", "Culo, cola, celo (cinta adhesiva)", "Casa, queso", "Café, cofia", "Coche, caja", "Cubo, cepo, capa", "Loro, lira", "Lata", "Luna, lana, lino", "Lima, loma, alma", "Loco, laca", "Lulú (perrito blanco), lelo, lila", "Losa, lazo", "Alfa (tenazas)", "Lucha, lago", "Lobo, lupa, lapa", "Sor (monja)", "Seta", "Sena (bajo la torre Eiffel), sien", "Sima (gruta)", "Saco", "Sol, sal", "Seso (cerebro)", "Sofá", "Sacho (rastrillo), soga, soja", "Sebo, sepia", "Faro de mar", "Foto (máquina de fotos), feto", "Faena del hogar", "Fama (alguien famoso)", "Foca", "Falo, fila", "Foso (con cocodrilos)", "Fofó (payaso), fofo", "Ficha, faja", "Efebo (ángel), fobia", "Hachero, grúa", "Chita (mona de Tarzán), gato", "China (muralla)", "Chama (mercadillo), goma", "Chico(a), jaca", "Chal, chulo, gol", "Chas (látigo), Chis (silencio), gas", "Chufa (horchata), jefe", "Chucho (tu perrita)", "Chivo, chapa", "Bar, vara", "Bota de vestir, bata", "Vino, viña, pana", "BUM (explosión)", "Vaca", "Vela, bola", "Vaso", "Bofia (policía en argot mafioso)", "Bache, bajo, vago", "Bebé, papá, pavo", "Torre, tarro, torero"];
const flashcards=[{"id": "prl-marco-1", "block": "marco", "page": "ley:a2", "ref": "LPRL · art. 2", "q": "Las disposiciones laborales preventivas tienen carácter de…", "a": "<b>Mínimo indisponible, mejorable por convenio</b>. El art. 2.2 permite mejorar y desarrollar la protección mediante convenios colectivos."}, {"id": "prl-marco-2", "block": "marco", "page": "ley:dfsegunda", "ref": "LPRL · disposiciones / anexos", "q": "La LPRL entró en vigor el…", "a": "<b>10 de febrero de 1996</b>. Su entrada se fijó a los tres meses de la publicación de 10/11/1995."}, {"id": "prl-marco-3", "block": "marco", "page": "rd:segunda-3", "ref": "RSP · disposiciones / anexos", "q": "La entrada en vigor general del RSP fue el…", "a": "<b>31 de marzo de 1997</b>. El art. 35 se exceptuó: entró en vigor doce meses después de la publicación, el 31/01/1998."}, {"id": "prl-ambito-1", "block": "ambito", "page": "ley:a3", "ref": "LPRL · art. 3", "q": "¿Queda excluido todo el personal de bomberos por su profesión?", "a": "<b>No; la excepción depende de las actividades y de sus particularidades</b>. El art. 3.2 condiciona la excepción a que las particularidades de ciertas actividades impidan aplicar la Ley."}, {"id": "prl-ambito-2", "block": "ambito", "page": "ley:a3", "ref": "LPRL · art. 3", "q": "En las actividades exceptuadas por el art. 3.2, la LPRL…", "a": "<b>Inspirará la normativa específica de protección</b>. La excepción no elimina el mandato de proteger la seguridad y salud mediante normativa específica."}, {"id": "prl-ambito-3", "block": "ambito", "page": "rd:cuarta", "ref": "RSP · disposiciones / anexos", "q": "Las obligaciones de auditoría del capítulo V del RSP se aplican a las Administraciones públicas…", "a": "<b>No; su normativa específica debe establecer instrumentos de control</b>. La disposición adicional cuarta.2 excluye esas obligaciones y exige instrumentos adecuados de control."}, {"id": "prl-conceptos-1", "block": "conceptos", "page": "ley:a4", "ref": "LPRL · art. 4", "q": "Para calificar la gravedad de un riesgo se valoran conjuntamente…", "a": "<b>La probabilidad y la severidad del daño</b>. El art. 4.2 utiliza ambos factores, no exclusivamente la probabilidad."}, {"id": "prl-conceptos-2", "block": "conceptos", "page": "ley:a4", "ref": "LPRL · art. 4", "q": "Una exposición inmediata a un agente con daño grave diferido…", "a": "<b>Puede constituir riesgo grave e inminente</b>. El art. 4.4 permite que el daño no se manifieste de forma inmediata."}, {"id": "prl-conceptos-3", "block": "conceptos", "page": "ley:a4", "ref": "LPRL · art. 4", "q": "La organización y ordenación del trabajo…", "a": "<b>Pueden ser condiciones de trabajo que generen riesgos</b>. La definición incluye características organizativas que influyen en la magnitud de los riesgos."}, {"id": "prl-organismos-1", "block": "organismos", "page": "ley:a9", "ref": "LPRL · art. 9", "q": "La vigilancia y control de la normativa preventiva corresponde específicamente a…", "a": "<b>La Inspección de Trabajo y Seguridad Social</b>. El art. 9 atribuye esa función a la ITSS, sin perjuicio de las competencias de otros órganos."}, {"id": "prl-organismos-2", "block": "organismos", "page": "ley:a13", "ref": "LPRL · art. 13", "q": "En los acuerdos de la CNSST, cada representante empresarial o sindical tiene…", "a": "<b>Dos votos</b>. Los representantes de las Administraciones tienen un voto cada uno; los empresariales y sindicales, dos."}, {"id": "prl-organismos-3", "block": "organismos", "page": "ley:a6", "ref": "LPRL · art. 6", "q": "El desarrollo reglamentario del art. 6 corresponde al Gobierno…", "a": "<b>Previa consulta a las organizaciones empresariales y sindicales más representativas</b>. El art. 6 regula materias como evaluación, organización preventiva y cualificación de servicios."}, {"id": "prl-principios-1", "block": "principios", "page": "ley:a15", "ref": "LPRL · art. 15", "q": "Según los principios preventivos, la primera actuación es…", "a": "<b>Evitar los riesgos</b>. El art. 15 comienza por evitar; se evalúan los riesgos que no puedan evitarse."}, {"id": "prl-principios-2", "block": "principios", "page": "ley:a15", "ref": "LPRL · art. 15", "q": "¿Qué protección debe anteponerse?", "a": "<b>La colectiva a la individual</b>. La prioridad aparece en el art. 15.1.h; no elimina la necesidad de EPI cuando procedan."}, {"id": "prl-principios-3", "block": "principios", "page": "ley:a14", "ref": "LPRL · art. 14", "q": "Contratar un servicio de prevención ajeno…", "a": "<b>No exime al empresario de su deber de protección</b>. El deber empresarial subsiste aunque se recurra a entidades especializadas."}, {"id": "prl-plan-1", "block": "plan", "page": "rd:a2", "ref": "RSP · art. 2", "q": "¿Quién aprueba el plan de prevención?", "a": "<b>La dirección de la empresa</b>. Debe ser asumido por toda la estructura y conocido por los trabajadores."}, {"id": "prl-plan-2", "block": "plan", "page": "ley:a16", "ref": "LPRL · art. 16", "q": "Los instrumentos esenciales para gestionar y aplicar el plan son…", "a": "<b>La evaluación y la planificación preventiva</b>. El art. 16.2 diferencia el plan de sus dos instrumentos esenciales."}, {"id": "prl-plan-3", "block": "plan", "page": "rd:a2", "ref": "RSP · art. 2", "q": "El documento único simplificado del RSP se admite en empresas…", "a": "<b>De hasta 50 trabajadores y sin actividades del anexo I</b>. El art. 2.4 exige ambos requisitos y medidas adaptadas con plazos de ejecución."}, {"id": "prl-evaluacion-1", "block": "evaluacion", "page": "rd:a6", "ref": "RSP · art. 6", "q": "Si se detectan daños a la salud, la evaluación de los puestos afectados…", "a": "<b>Debe revisarse</b>. El art. 6.1 exige revisar, considerando entre otros elementos la investigación del daño."}, {"id": "prl-evaluacion-2", "block": "evaluacion", "page": "rd:a5", "ref": "RSP · art. 5", "q": "Si existen dudas sobre el resultado de una evaluación…", "a": "<b>Se adoptan las medidas más favorables desde el punto de vista preventivo</b>. El procedimiento debe proporcionar confianza en su resultado."}, {"id": "prl-evaluacion-3", "block": "evaluacion", "page": "rd:a4", "ref": "RSP · art. 4", "q": "La evaluación debe considerar que el trabajador sea especialmente sensible…", "a": "<b>A los riesgos por sus características personales o estado biológico conocido</b>. Se valoran tanto las condiciones del trabajo como las características de quienes lo desempeñan."}, {"id": "prl-planificacion-1", "block": "planificacion", "page": "ley:a16", "ref": "LPRL · art. 16", "q": "Para cada actividad preventiva deben figurar…", "a": "<b>Plazo, responsables y recursos humanos y materiales</b>. El art. 16.2.b exige esas concreciones; el art. 9 RSP añade recursos económicos."}, {"id": "prl-planificacion-2", "block": "planificacion", "page": "rd:a9", "ref": "RSP · art. 9", "q": "Si la actividad preventiva se planifica para más de un año…", "a": "<b>Se establece un programa anual de actividades</b>. El art. 9.3 exige ese programa sin eliminar seguimiento y control periódico."}, {"id": "prl-planificacion-3", "block": "planificacion", "page": "rd:a8", "ref": "RSP · art. 8", "q": "Las prioridades de la planificación atienden a…", "a": "<b>Magnitud del riesgo y número de trabajadores expuestos</b>. El art. 8 prioriza la eliminación o control de riesgos atendiendo a esos dos factores."}, {"id": "prl-equipos-1", "block": "equipos", "page": "ley:a17", "ref": "LPRL · art. 17", "q": "Los EPI se utilizan cuando…", "a": "<b>El riesgo no pueda evitarse o limitarse suficientemente por protección colectiva u organización</b>. El art. 17.2 establece su función dentro del conjunto de medidas preventivas."}, {"id": "prl-equipos-2", "block": "equipos", "page": "ley:a17", "ref": "LPRL · art. 17", "q": "El mantenimiento de equipos con riesgos específicos lo realizan…", "a": "<b>Trabajadores específicamente capacitados</b>. El art. 17.1 diferencia el uso reservado y las tareas técnicas por personal capacitado."}, {"id": "prl-equipos-3", "block": "equipos", "page": "ley:a41", "ref": "LPRL · art. 41", "q": "La información sobre utilización y riesgos de los productos debe…", "a": "<b>Facilitarla el suministrador y hacerla llegar el empresario de forma comprensible</b>. El art. 41 distribuye obligaciones entre fabricantes, importadores, suministradores y empresario."}, {"id": "prl-informacion-1", "block": "informacion", "page": "ley:a18", "ref": "LPRL · art. 18", "q": "La información de riesgos específicos del puesto se facilita…", "a": "<b>Directamente a cada trabajador</b>. El cauce representativo para información general no sustituye la información directa del puesto."}, {"id": "prl-informacion-2", "block": "informacion", "page": "ley:a19", "ref": "LPRL · art. 19", "q": "Si la formación preventiva se realiza fuera de jornada…", "a": "<b>Se descuenta de la jornada el tiempo invertido</b>. El art. 19.2 mantiene la ausencia de coste y prevé esa compensación de tiempo."}, {"id": "prl-informacion-3", "block": "informacion", "page": "ley:a19", "ref": "LPRL · art. 19", "q": "La formación debe darse al contratar…", "a": "<b>Cualquiera que sea la modalidad o duración del contrato</b>. También se imparte ante cambios de funciones, nuevas tecnologías o equipos."}, {"id": "prl-emergencias-1", "block": "emergencias", "page": "ley:a20", "ref": "LPRL · art. 20", "q": "El artículo 20 contempla expresamente…", "a": "<b>Primeros auxilios, lucha contra incendios y evacuación</b>. Son las tres materias citadas para las medidas de emergencia."}, {"id": "prl-emergencias-2", "block": "emergencias", "page": "ley:a20", "ref": "LPRL · art. 20", "q": "Al analizar emergencias debe tenerse en cuenta…", "a": "<b>La posible presencia de personas ajenas a la empresa</b>. El art. 20 añade este factor al tamaño y actividad de la empresa."}, {"id": "prl-emergencias-3", "block": "emergencias", "page": "ley:a20", "ref": "LPRL · art. 20", "q": "El personal designado para emergencias debe…", "a": "<b>Tener formación, número suficiente y material adecuado</b>. La empresa también comprueba periódicamente el funcionamiento de las medidas."}, {"id": "prl-paralizacion-1", "block": "paralizacion", "page": "ley:a21", "ref": "LPRL · art. 21", "q": "La autoridad laboral ratifica o anula la paralización acordada por representantes en…", "a": "<b>24 horas</b>. La comunicación a empresa y autoridad es inmediata; el plazo de decisión es 24 horas."}, {"id": "prl-paralizacion-2", "block": "paralizacion", "page": "ley:a21", "ref": "LPRL · art. 21", "q": "Si no se reúne con urgencia la representación legal, pueden acordar paralizar…", "a": "<b>Los delegados de prevención por decisión mayoritaria</b>. Es la vía subsidiaria prevista en el art. 21.3."}, {"id": "prl-paralizacion-3", "block": "paralizacion", "page": "ley:a44", "ref": "LPRL · art. 44", "q": "La empresa puede impugnar una paralización inspectora en…", "a": "<b>3 días hábiles, sin dejar de cumplirla inmediatamente</b>. La autoridad laboral debe resolver la impugnación en un máximo de 24 horas."}, {"id": "prl-salud-1", "block": "salud", "page": "ley:a22", "ref": "LPRL · art. 22", "q": "La regla general de la vigilancia de la salud es…", "a": "<b>El consentimiento del trabajador, con excepciones legales</b>. Las excepciones del art. 22.1 exigen informe previo de los representantes."}, {"id": "prl-salud-2", "block": "salud", "page": "ley:a22", "ref": "LPRL · art. 22", "q": "El empresario recibe ordinariamente…", "a": "<b>Conclusiones de aptitud y necesidad de medidas preventivas</b>. El acceso a información médica personal está limitado por confidencialidad."}, {"id": "prl-salud-3", "block": "salud", "page": "rd:a37", "ref": "RSP · art. 37", "q": "Después de una ausencia prolongada por motivos de salud, el RSP contempla…", "a": "<b>Una evaluación de salud para detectar posibles orígenes profesionales y recomendar protección</b>. El art. 37.3.b incluye ese supuesto junto a evaluación inicial y vigilancia periódica."}, {"id": "prl-documentacion-1", "block": "documentacion", "page": "ley:a23", "ref": "LPRL · art. 23", "q": "La relación del art. 23.1.e incluye daños con incapacidad…", "a": "<b>Superior a un día de trabajo</b>. Es el umbral específico de esa relación; no elimina los deberes de notificación de daños."}, {"id": "prl-documentacion-2", "block": "documentacion", "page": "ley:a24", "ref": "LPRL · art. 24", "q": "El empresario titular del centro debe…", "a": "<b>Informar e instruir sobre riesgos, medidas y emergencias del centro</b>. El art. 24.2 establece ese deber hacia los empresarios que desarrollan actividades en el centro."}, {"id": "prl-documentacion-3", "block": "documentacion", "page": "ley:a24", "ref": "LPRL · art. 24", "q": "La vigilancia del empresario principal del art. 24.3 se refiere a…", "a": "<b>Contratas de su propia actividad en sus propios centros</b>. Conserva ambas condiciones para no ampliar indebidamente la regla."}, {"id": "prl-proteccion-1", "block": "proteccion", "page": "ley:a26", "ref": "LPRL · art. 26", "q": "La secuencia protectora de la maternidad es…", "a": "<b>Adaptación, cambio compatible y, si procede, suspensión por riesgo</b>. Los pasos y sus requisitos se regulan en los apartados 1 a 3 del art. 26."}, {"id": "prl-proteccion-2", "block": "proteccion", "page": "ley:a27", "ref": "LPRL · art. 27", "q": "La evaluación especial de menores se refiere a quienes tienen…", "a": "<b>Menos de 18 años</b>. Se realiza antes de incorporarse y ante modificaciones importantes de sus condiciones."}, {"id": "prl-proteccion-3", "block": "proteccion", "page": "ley:a28", "ref": "LPRL · art. 28", "q": "En una ETT, formación y vigilancia de la salud corresponden a…", "a": "<b>La empresa de trabajo temporal</b>. La usuaria es responsable de las condiciones de ejecución; el artículo distribuye las obligaciones."}, {"id": "prl-obligaciones-1", "block": "obligaciones", "page": "ley:a29", "ref": "LPRL · art. 29", "q": "Ante una situación que razonablemente entrañe riesgo, el trabajador informa…", "a": "<b>De inmediato a los destinatarios previstos en el art. 29</b>. Los destinatarios son el superior directo y los trabajadores designados o, en su caso, el servicio de prevención."}, {"id": "prl-obligaciones-2", "block": "obligaciones", "page": "ley:a29", "ref": "LPRL · art. 29", "q": "Los dispositivos de seguridad deben…", "a": "<b>Utilizarse correctamente y no ponerse fuera de funcionamiento</b>. Es un deber expreso del art. 29.2.3.º."}, {"id": "prl-obligaciones-3", "block": "obligaciones", "page": "ley:a29", "ref": "LPRL · art. 29", "q": "El incumplimiento preventivo de un funcionario puede ser…", "a": "<b>Falta conforme a su régimen disciplinario</b>. El art. 29.3 remite al régimen disciplinario aplicable, sin establecer delito automático."}, {"id": "prl-modalidades-1", "block": "modalidades", "page": "rd:a11", "ref": "RSP · art. 11", "q": "Un empresario con 25 trabajadores puede asumir personalmente la prevención si…", "a": "<b>Hay único centro y cumple el resto de requisitos, excluida vigilancia de salud</b>. Se exigen simultáneamente plantilla, centro único en ese tramo, actividad no anexo I, presencia y capacidad."}, {"id": "prl-modalidades-2", "block": "modalidades", "page": "rd:a11", "ref": "RSP · art. 11", "q": "La asunción personal por el empresario excluye siempre…", "a": "<b>Las actividades de vigilancia de la salud</b>. Deben cubrirse por otra modalidad preventiva."}, {"id": "prl-modalidades-3", "block": "modalidades", "page": "rd:a13", "ref": "RSP · art. 13", "q": "Los trabajadores designados deben contar con…", "a": "<b>Capacidad, tiempo, medios y número suficiente</b>. La adecuación depende del tamaño, riesgos y distribución de la empresa."}, {"id": "prl-propio-1", "block": "propio", "page": "rd:a14", "ref": "RSP · art. 14", "q": "El umbral general que obliga a servicio propio por tamaño es…", "a": "<b>Más de 500 trabajadores</b>. La letra a usa más de 500; la letra b abarca 250–500 con actividades del anexo I."}, {"id": "prl-propio-2", "block": "propio", "page": "rd:a14", "ref": "RSP · art. 14", "q": "Una empresa de 250 trabajadores con actividad del anexo I debe…", "a": "<b>Constituir servicio de prevención propio</b>. El tramo de 250 a 500 incluye sus extremos."}, {"id": "prl-propio-3", "block": "propio", "page": "rd:a15", "ref": "RSP · art. 15", "q": "El servicio propio contará al menos con…", "a": "<b>Dos especialidades o disciplinas preventivas</b>. El art. 15 fija dos; no lo confundas con mancomunados o ajenos."}, {"id": "prl-ajeno-1", "block": "ajeno", "page": "rd:a21", "ref": "RSP · art. 21", "q": "El servicio mancomunado tiene consideración de…", "a": "<b>Servicio propio de las empresas participantes</b>. Debe contar al menos con tres disciplinas preventivas."}, {"id": "prl-ajeno-2", "block": "ajeno", "page": "rd:a18", "ref": "RSP · art. 18", "q": "Un servicio de prevención ajeno debe contar con…", "a": "<b>Las cuatro especialidades o disciplinas preventivas</b>. El mínimo de dos es del SPP y el de tres del mancomunado."}, {"id": "prl-ajeno-3", "block": "ajeno", "page": "rd:a25", "ref": "RSP · art. 25", "q": "El silencio en la solicitud de acreditación como SPA es…", "a": "<b>Desestimatorio</b>. El plazo ordinario es tres meses, ampliado a seis en el supuesto del art. 25.3."}, {"id": "prl-recursos-1", "block": "recursos", "page": "ley:a32bis", "ref": "LPRL · art. 32 bis", "q": "¿Qué puede exigir la presencia de recursos preventivos?", "a": "<b>Un requerimiento de la ITSS por las condiciones detectadas</b>. Es uno de los tres supuestos del art. 32 bis.1."}, {"id": "prl-recursos-2", "block": "recursos", "page": "ley:a32bis", "ref": "LPRL · art. 32 bis", "q": "Otro trabajador asignado expresamente a presencia preventiva necesita, como mínimo…", "a": "<b>Formación de nivel básico, además de conocimientos, cualificación y experiencia necesarios</b>. El art. 32 bis.4 exige ese conjunto de condiciones."}, {"id": "prl-recursos-3", "block": "recursos", "page": "rd:a22bis", "ref": "RSP · art. 22 bis", "q": "La presencia del recurso preventivo es una medida…", "a": "<b>Complementaria a las restantes medidas preventivas</b>. Su finalidad es vigilar cumplimiento y eficacia mientras se mantiene la situación."}, {"id": "prl-consulta-1", "block": "consulta", "page": "ley:a33", "ref": "LPRL · art. 33", "q": "Las decisiones preventivas del art. 33 se consultan…", "a": "<b>Con la debida antelación</b>. La consulta debe permitir participación efectiva antes de la decisión."}, {"id": "prl-consulta-2", "block": "consulta", "page": "ley:a34", "ref": "LPRL · art. 34", "q": "El cauce representativo del art. 34 se prevé en empresas con…", "a": "<b>Seis o más trabajadores</b>. No se debe confundir ese umbral con el del Comité de Seguridad y Salud."}, {"id": "prl-consulta-3", "block": "consulta", "page": "ley:a33", "ref": "LPRL · art. 33", "q": "La designación de trabajadores para medidas de emergencia…", "a": "<b>Está incluida entre las cuestiones objeto de consulta</b>. El art. 33.1.c la incluye expresamente."}, {"id": "prl-delegados-1", "block": "delegados", "page": "ley:a35", "ref": "LPRL · art. 35", "q": "A una empresa con exactamente 100 trabajadores le corresponden, según escala general…", "a": "<b>2 delegados de prevención</b>. El primer tramo es 50–100; 101 abre el tramo de tres."}, {"id": "prl-delegados-2", "block": "delegados", "page": "ley:a35", "ref": "LPRL · art. 35", "q": "Con exactamente 500 trabajadores, la escala general establece…", "a": "<b>3 delegados de prevención</b>. 500 cierra el tramo 101–500; a partir de 501 son cuatro."}, {"id": "prl-delegados-3", "block": "delegados", "page": "ley:a35", "ref": "LPRL · art. 35", "q": "En contratos de hasta un año, cada 200 días trabajados o fracción computa como…", "a": "<b>Un trabajador más</b>. Se cuentan los días del año anterior a la designación, no solo el día de la elección."}, {"id": "prl-facultades-1", "block": "facultades", "page": "ley:a36", "ref": "LPRL · art. 36", "q": "El plazo ordinario para los informes de consulta de delegados es…", "a": "<b>15 días</b>. Para medidas contra riesgos inminentes se reduce al tiempo imprescindible."}, {"id": "prl-facultades-2", "block": "facultades", "page": "ley:a36", "ref": "LPRL · art. 36", "q": "La negativa empresarial a adoptar medidas propuestas por el delegado debe ser…", "a": "<b>Motivada</b>. El art. 36.4 exige motivación."}, {"id": "prl-facultades-3", "block": "facultades", "page": "ley:a37", "ref": "LPRL · art. 37", "q": "Las reuniones del Comité de Seguridad y Salud son…", "a": "<b>Trabajo efectivo sin imputación al crédito horario</b>. El art. 37.1 establece expresamente esa excepción al crédito."}, {"id": "prl-comite-1", "block": "comite", "page": "ley:a38", "ref": "LPRL · art. 38", "q": "El Comité de Seguridad y Salud se constituye con…", "a": "<b>50 o más trabajadores</b>. El umbral incluye exactamente 50 y puede referirse a empresa o centro de trabajo."}, {"id": "prl-comite-2", "block": "comite", "page": "ley:a38", "ref": "LPRL · art. 38", "q": "El comité se reúne ordinariamente…", "a": "<b>Trimestralmente</b>. También cuando lo solicite alguna de sus representaciones."}, {"id": "prl-comite-3", "block": "comite", "page": "ley:a38", "ref": "LPRL · art. 38", "q": "Los técnicos de prevención que no integran el comité participan…", "a": "<b>Con voz y sin voto</b>. La misma regla se prevé para delegados sindicales no integrantes en los términos del artículo."}, {"id": "prl-responsabilidades-1", "block": "responsabilidades", "page": "ley:a42", "ref": "LPRL · art. 42", "q": "La responsabilidad administrativa preventiva puede ser compatible con…", "a": "<b>Indemnizaciones y recargo de prestaciones</b>. El art. 42.3 declara esa compatibilidad en los términos de la normativa aplicable."}, {"id": "prl-responsabilidades-2", "block": "responsabilidades", "page": "ley:a43", "ref": "LPRL · art. 43", "q": "Un requerimiento de subsanación de la ITSS…", "a": "<b>No impide la propuesta de sanción correspondiente</b>. El art. 43 exige requerimiento escrito con deficiencias y plazo, sin perjuicio de sanción."}, {"id": "prl-responsabilidades-3", "block": "responsabilidades", "page": "ley:a45", "ref": "LPRL · art. 45", "q": "Los artículos 45–52 de la LPRL están…", "a": "<b>Derogados</b>. La consolidación los identifica como derogados; evita estudiar sus versiones históricas como vigentes."}, {"id": "prl-auditoria-1", "block": "auditoria", "page": "rd:a30", "ref": "RSP · art. 30", "q": "La primera auditoría se realiza dentro de los 12 meses siguientes a…", "a": "<b>Disponer de la planificación de la actividad preventiva</b>. El inicio del cómputo se fija en el art. 30.4."}, {"id": "prl-auditoria-2", "block": "auditoria", "page": "rd:a30", "ref": "RSP · art. 30", "q": "La repetición ordinaria es cada…", "a": "<b>4 años, o 2 si hay actividades del anexo I</b>. Puede ampliarse la revisión en dos años por acuerdo sobre modalidad con representación especializada."}, {"id": "prl-auditoria-3", "block": "auditoria", "page": "rd:a29", "ref": "RSP · art. 29", "q": "La excepción de auditoría de empresas pequeñas exige…", "a": "<b>Hasta 50, sin anexo I, recursos propios, eficacia evidente y notificación, con posibilidad de requerimiento</b>. El art. 29.3 recoge requisitos acumulativos; la autoridad puede exigir auditoría según el apartado 4."}, {"id": "prl-formacion-1", "block": "formacion", "page": "rd:a35", "ref": "RSP · art. 35", "q": "La duración mínima del programa básico para actividades del anexo I es…", "a": "<b>50 horas</b>. En las demás empresas la vía formativa básica es de al menos 30 horas."}, {"id": "prl-formacion-2", "block": "formacion", "page": "rd:a36", "ref": "RSP · art. 36", "q": "El programa de nivel intermedio tiene duración no inferior a…", "a": "<b>300 horas</b>. El art. 36 remite al programa del anexo V."}, {"id": "prl-formacion-3", "block": "formacion", "page": "rd:a37", "ref": "RSP · art. 37", "q": "Para funciones de nivel superior, el art. 37.2 exige…", "a": "<b>Titulación universitaria oficial y formación universitaria acreditada de al menos 600 horas</b>. Los requisitos sanitarios específicos se añaden para vigilancia y control de la salud."}, {"id": "prl-anexos-1", "block": "anexos", "page": "rd:ani", "ref": "RSP · disposiciones / anexos", "q": "El anexo I incluye exposición a agentes biológicos de los grupos…", "a": "<b>3 y 4</b>. El apartado d recoge los grupos 3 y 4."}, {"id": "prl-anexos-2", "block": "anexos", "page": "rd:aniv", "ref": "RSP · disposiciones / anexos", "q": "El programa de formación de nivel básico figura en el anexo…", "a": "<b>IV</b>. II es notificación sobre auditoría; V intermedio; VI superior."}, {"id": "prl-anexos-3", "block": "anexos", "page": "rd:anviii", "ref": "RSP · disposiciones / anexos", "q": "¿Qué anexos tratan específicamente de embarazo o lactancia?", "a": "<b>VII y VIII</b>. El VII recoge posibles influencias negativas; el VIII, agentes y condiciones de no exposición en los términos legales."}];
const quizdata=[{"id": "prl-q1", "block": "marco", "page": "ley:a2", "ref": "LPRL · art. 2", "q": "Las disposiciones laborales preventivas tienen carácter de…", "options": ["Máximo que no puede superarse", "Orientación voluntaria", "Mínimo que el trabajador puede renunciar a aplicar", "Mínimo indisponible, mejorable por convenio"], "correct": 3, "explanation": "El art. 2.2 permite mejorar y desarrollar la protección mediante convenios colectivos."}, {"id": "prl-q2", "block": "marco", "page": "ley:dfsegunda", "ref": "LPRL · disposiciones / anexos", "q": "La LPRL entró en vigor el…", "options": ["10 de febrero de 1996", "8 de noviembre de 1995", "10 de noviembre de 1995", "31 de marzo de 1997"], "correct": 0, "explanation": "Su entrada se fijó a los tres meses de la publicación de 10/11/1995."}, {"id": "prl-q3", "block": "marco", "page": "rd:segunda-3", "ref": "RSP · disposiciones / anexos", "q": "La entrada en vigor general del RSP fue el…", "options": ["10 de febrero de 1996", "31 de marzo de 1997", "17 de enero de 1997", "31 de enero de 1997"], "correct": 1, "explanation": "El art. 35 se exceptuó: entró en vigor doce meses después de la publicación, el 31/01/1998."}, {"id": "prl-q4", "block": "ambito", "page": "ley:a3", "ref": "LPRL · art. 3", "q": "¿Queda excluido todo el personal de bomberos por su profesión?", "options": ["Sí, incluso en mantenimiento y formación", "Solo se aplica al personal administrativo del parque", "No; la excepción depende de las actividades y de sus particularidades", "Sí, por pertenecer a protección civil"], "correct": 2, "explanation": "El art. 3.2 condiciona la excepción a que las particularidades de ciertas actividades impidan aplicar la Ley."}, {"id": "prl-q5", "block": "ambito", "page": "ley:a3", "ref": "LPRL · art. 3", "q": "En las actividades exceptuadas por el art. 3.2, la LPRL…", "options": ["No tiene ninguna función", "Se sustituye siempre por un convenio", "Solo protege a mandos", "Inspirará la normativa específica de protección"], "correct": 3, "explanation": "La excepción no elimina el mandato de proteger la seguridad y salud mediante normativa específica."}, {"id": "prl-q6", "block": "ambito", "page": "rd:cuarta", "ref": "RSP · disposiciones / anexos", "q": "Las obligaciones de auditoría del capítulo V del RSP se aplican a las Administraciones públicas…", "options": ["No; su normativa específica debe establecer instrumentos de control", "Sí, cada cuatro años sin excepción", "Sí, cada dos años en todos los servicios", "Solo si hay más de 50 empleados"], "correct": 0, "explanation": "La disposición adicional cuarta.2 excluye esas obligaciones y exige instrumentos adecuados de control."}, {"id": "prl-q7", "block": "conceptos", "page": "ley:a4", "ref": "LPRL · art. 4", "q": "Para calificar la gravedad de un riesgo se valoran conjuntamente…", "options": ["La urgencia y el coste económico", "La probabilidad y la severidad del daño", "Solo el número de expuestos", "La duración y el precio del equipo"], "correct": 1, "explanation": "El art. 4.2 utiliza ambos factores, no exclusivamente la probabilidad."}, {"id": "prl-q8", "block": "conceptos", "page": "ley:a4", "ref": "LPRL · art. 4", "q": "Una exposición inmediata a un agente con daño grave diferido…", "options": ["Solo es riesgo leve", "No constituye riesgo laboral", "Puede constituir riesgo grave e inminente", "Nunca es inminente si no hay síntomas"], "correct": 2, "explanation": "El art. 4.4 permite que el daño no se manifieste de forma inmediata."}, {"id": "prl-q9", "block": "conceptos", "page": "ley:a4", "ref": "LPRL · art. 4", "q": "La organización y ordenación del trabajo…", "options": ["Están excluidas de la definición", "Solo son relevantes en oficinas", "Solo cuentan si causan lesiones físicas", "Pueden ser condiciones de trabajo que generen riesgos"], "correct": 3, "explanation": "La definición incluye características organizativas que influyen en la magnitud de los riesgos."}, {"id": "prl-q10", "block": "organismos", "page": "ley:a9", "ref": "LPRL · art. 9", "q": "La vigilancia y control de la normativa preventiva corresponde específicamente a…", "options": ["La Inspección de Trabajo y Seguridad Social", "La CNSST exclusivamente", "El Comité de empresa en exclusiva", "El servicio médico exclusivamente"], "correct": 0, "explanation": "El art. 9 atribuye esa función a la ITSS, sin perjuicio de las competencias de otros órganos."}, {"id": "prl-q11", "block": "organismos", "page": "ley:a13", "ref": "LPRL · art. 13", "q": "En los acuerdos de la CNSST, cada representante empresarial o sindical tiene…", "options": ["Voto solo consultivo", "Dos votos", "Un voto", "Tres votos"], "correct": 1, "explanation": "Los representantes de las Administraciones tienen un voto cada uno; los empresariales y sindicales, dos."}, {"id": "prl-q12", "block": "organismos", "page": "ley:a6", "ref": "LPRL · art. 6", "q": "El desarrollo reglamentario del art. 6 corresponde al Gobierno…", "options": ["Sin consulta alguna", "Solo a propuesta del Comité de Seguridad y Salud", "Previa consulta a las organizaciones empresariales y sindicales más representativas", "Con autorización individual de cada empresa"], "correct": 2, "explanation": "El art. 6 regula materias como evaluación, organización preventiva y cualificación de servicios."}, {"id": "prl-q13", "block": "principios", "page": "ley:a15", "ref": "LPRL · art. 15", "q": "Según los principios preventivos, la primera actuación es…", "options": ["Evaluar todos los riesgos antes de intentar evitarlos", "Entregar siempre un EPI como primera medida", "Compensar económicamente el riesgo", "Evitar los riesgos"], "correct": 3, "explanation": "El art. 15 comienza por evitar; se evalúan los riesgos que no puedan evitarse."}, {"id": "prl-q14", "block": "principios", "page": "ley:a15", "ref": "LPRL · art. 15", "q": "¿Qué protección debe anteponerse?", "options": ["La colectiva a la individual", "La individual a la colectiva", "La más barata en todo caso", "La voluntaria a la obligatoria"], "correct": 0, "explanation": "La prioridad aparece en el art. 15.1.h; no elimina la necesidad de EPI cuando procedan."}, {"id": "prl-q15", "block": "principios", "page": "ley:a14", "ref": "LPRL · art. 14", "q": "Contratar un servicio de prevención ajeno…", "options": ["Sustituye la obligación de integrar la prevención", "No exime al empresario de su deber de protección", "Transfiere toda responsabilidad al servicio", "Permite cobrar la prevención a los trabajadores"], "correct": 1, "explanation": "El deber empresarial subsiste aunque se recurra a entidades especializadas."}, {"id": "prl-q16", "block": "plan", "page": "rd:a2", "ref": "RSP · art. 2", "q": "¿Quién aprueba el plan de prevención?", "options": ["Los delegados por unanimidad", "Cada trabajador individualmente", "La dirección de la empresa", "La ITSS en todo caso"], "correct": 2, "explanation": "Debe ser asumido por toda la estructura y conocido por los trabajadores."}, {"id": "prl-q17", "block": "plan", "page": "ley:a16", "ref": "LPRL · art. 16", "q": "Los instrumentos esenciales para gestionar y aplicar el plan son…", "options": ["La auditoría y la sanción", "El convenio y el contrato", "El comité y la mutua", "La evaluación y la planificación preventiva"], "correct": 3, "explanation": "El art. 16.2 diferencia el plan de sus dos instrumentos esenciales."}, {"id": "prl-q18", "block": "plan", "page": "rd:a2", "ref": "RSP · art. 2", "q": "El documento único simplificado del RSP se admite en empresas…", "options": ["De hasta 50 trabajadores y sin actividades del anexo I", "De hasta 500 trabajadores de cualquier actividad", "De menos de 25 sin más requisitos", "De hasta 50 aunque realicen actividades del anexo I"], "correct": 0, "explanation": "El art. 2.4 exige ambos requisitos y medidas adaptadas con plazos de ejecución."}, {"id": "prl-q19", "block": "evaluacion", "page": "rd:a6", "ref": "RSP · art. 6", "q": "Si se detectan daños a la salud, la evaluación de los puestos afectados…", "options": ["Se mantiene hasta el siguiente plazo fijo de cinco años", "Debe revisarse", "Solo se revisa si lo pide el accidentado", "Se destruye y sustituye por el parte"], "correct": 1, "explanation": "El art. 6.1 exige revisar, considerando entre otros elementos la investigación del daño."}, {"id": "prl-q20", "block": "evaluacion", "page": "rd:a5", "ref": "RSP · art. 5", "q": "Si existen dudas sobre el resultado de una evaluación…", "options": ["No se actúa hasta que ocurra un daño", "Se presume ausencia de riesgo", "Se adoptan las medidas más favorables desde el punto de vista preventivo", "Se elige siempre la solución más económica"], "correct": 2, "explanation": "El procedimiento debe proporcionar confianza en su resultado."}, {"id": "prl-q21", "block": "evaluacion", "page": "rd:a4", "ref": "RSP · art. 4", "q": "La evaluación debe considerar que el trabajador sea especialmente sensible…", "options": ["Solo si existe incapacidad reconocida", "Únicamente si lo exige por escrito", "Solo después de un accidente", "A los riesgos por sus características personales o estado biológico conocido"], "correct": 3, "explanation": "Se valoran tanto las condiciones del trabajo como las características de quienes lo desempeñan."}, {"id": "prl-q22", "block": "planificacion", "page": "ley:a16", "ref": "LPRL · art. 16", "q": "Para cada actividad preventiva deben figurar…", "options": ["Plazo, responsables y recursos humanos y materiales", "Solo presupuesto total", "Solo nombre del evaluador", "Únicamente fecha de la auditoría"], "correct": 0, "explanation": "El art. 16.2.b exige esas concreciones; el art. 9 RSP añade recursos económicos."}, {"id": "prl-q23", "block": "planificacion", "page": "rd:a9", "ref": "RSP · art. 9", "q": "Si la actividad preventiva se planifica para más de un año…", "options": ["Se sustituye el plan por una auditoría", "Se establece un programa anual de actividades", "Se aplaza toda revisión hasta el final", "No se necesita planificación"], "correct": 1, "explanation": "El art. 9.3 exige ese programa sin eliminar seguimiento y control periódico."}, {"id": "prl-q24", "block": "planificacion", "page": "rd:a8", "ref": "RSP · art. 8", "q": "Las prioridades de la planificación atienden a…", "options": ["Solo precio de las medidas", "Solo orden de llegada de las solicitudes", "Magnitud del riesgo y número de trabajadores expuestos", "Solo antigüedad de la plantilla"], "correct": 2, "explanation": "El art. 8 prioriza la eliminación o control de riesgos atendiendo a esos dos factores."}, {"id": "prl-q25", "block": "equipos", "page": "ley:a17", "ref": "LPRL · art. 17", "q": "Los EPI se utilizan cuando…", "options": ["Siempre como única medida", "Solo si el trabajador los compra", "Solo tras un accidente", "El riesgo no pueda evitarse o limitarse suficientemente por protección colectiva u organización"], "correct": 3, "explanation": "El art. 17.2 establece su función dentro del conjunto de medidas preventivas."}, {"id": "prl-q26", "block": "equipos", "page": "ley:a17", "ref": "LPRL · art. 17", "q": "El mantenimiento de equipos con riesgos específicos lo realizan…", "options": ["Trabajadores específicamente capacitados", "Cualquier usuario sin formación", "Solo los delegados de prevención", "Exclusivamente el empresario personalmente"], "correct": 0, "explanation": "El art. 17.1 diferencia el uso reservado y las tareas técnicas por personal capacitado."}, {"id": "prl-q27", "block": "equipos", "page": "ley:a41", "ref": "LPRL · art. 41", "q": "La información sobre utilización y riesgos de los productos debe…", "options": ["Ser accesible solo a mandos", "Facilitarla el suministrador y hacerla llegar el empresario de forma comprensible", "Mantenerse solo en poder del fabricante", "Sustituir la formación preventiva"], "correct": 1, "explanation": "El art. 41 distribuye obligaciones entre fabricantes, importadores, suministradores y empresario."}, {"id": "prl-q28", "block": "informacion", "page": "ley:a18", "ref": "LPRL · art. 18", "q": "La información de riesgos específicos del puesto se facilita…", "options": ["Solo al delegado sindical", "Únicamente si el trabajador la solicita", "Directamente a cada trabajador", "Solo al comité"], "correct": 2, "explanation": "El cauce representativo para información general no sustituye la información directa del puesto."}, {"id": "prl-q29", "block": "informacion", "page": "ley:a19", "ref": "LPRL · art. 19", "q": "Si la formación preventiva se realiza fuera de jornada…", "options": ["La paga el trabajador", "No se compensa en ningún caso", "Solo se compensa si hubo examen", "Se descuenta de la jornada el tiempo invertido"], "correct": 3, "explanation": "El art. 19.2 mantiene la ausencia de coste y prevé esa compensación de tiempo."}, {"id": "prl-q30", "block": "informacion", "page": "ley:a19", "ref": "LPRL · art. 19", "q": "La formación debe darse al contratar…", "options": ["Cualquiera que sea la modalidad o duración del contrato", "Solo en contratos indefinidos", "Solo si dura más de un año", "Solo después del período de prueba"], "correct": 0, "explanation": "También se imparte ante cambios de funciones, nuevas tecnologías o equipos."}, {"id": "prl-q31", "block": "emergencias", "page": "ley:a20", "ref": "LPRL · art. 20", "q": "El artículo 20 contempla expresamente…", "options": ["Solo contratación de una ambulancia", "Primeros auxilios, lucha contra incendios y evacuación", "Solo extinción y rescate técnico", "Solo evacuación de empleados"], "correct": 1, "explanation": "Son las tres materias citadas para las medidas de emergencia."}, {"id": "prl-q32", "block": "emergencias", "page": "ley:a20", "ref": "LPRL · art. 20", "q": "Al analizar emergencias debe tenerse en cuenta…", "options": ["Solo el turno de mañana", "Únicamente el valor de los bienes", "La posible presencia de personas ajenas a la empresa", "Solo la plantilla fija"], "correct": 2, "explanation": "El art. 20 añade este factor al tamaño y actividad de la empresa."}, {"id": "prl-q33", "block": "emergencias", "page": "ley:a20", "ref": "LPRL · art. 20", "q": "El personal designado para emergencias debe…", "options": ["Ser necesariamente delegado de prevención", "Carecer de otras funciones en todo caso", "Actuar sin comprobaciones periódicas", "Tener formación, número suficiente y material adecuado"], "correct": 3, "explanation": "La empresa también comprueba periódicamente el funcionamiento de las medidas."}, {"id": "prl-q34", "block": "paralizacion", "page": "ley:a21", "ref": "LPRL · art. 21", "q": "La autoridad laboral ratifica o anula la paralización acordada por representantes en…", "options": ["24 horas", "15 días", "3 días hábiles", "Un mes"], "correct": 0, "explanation": "La comunicación a empresa y autoridad es inmediata; el plazo de decisión es 24 horas."}, {"id": "prl-q35", "block": "paralizacion", "page": "ley:a21", "ref": "LPRL · art. 21", "q": "Si no se reúne con urgencia la representación legal, pueden acordar paralizar…", "options": ["Solo el director del servicio de prevención", "Los delegados de prevención por decisión mayoritaria", "Un delegado por sí solo en cualquier caso", "Solo todos los trabajadores por unanimidad"], "correct": 1, "explanation": "Es la vía subsidiaria prevista en el art. 21.3."}, {"id": "prl-q36", "block": "paralizacion", "page": "ley:a44", "ref": "LPRL · art. 44", "q": "La empresa puede impugnar una paralización inspectora en…", "options": ["15 días naturales, suspendiendo la orden", "Un mes, sin comunicación", "3 días hábiles, sin dejar de cumplirla inmediatamente", "24 horas, suspendiendo la orden"], "correct": 2, "explanation": "La autoridad laboral debe resolver la impugnación en un máximo de 24 horas."}, {"id": "prl-q37", "block": "salud", "page": "ley:a22", "ref": "LPRL · art. 22", "q": "La regla general de la vigilancia de la salud es…", "options": ["La obligatoriedad absoluta", "La exclusión del personal temporal", "La libre elección del empresario sin límites", "El consentimiento del trabajador, con excepciones legales"], "correct": 3, "explanation": "Las excepciones del art. 22.1 exigen informe previo de los representantes."}, {"id": "prl-q38", "block": "salud", "page": "ley:a22", "ref": "LPRL · art. 22", "q": "El empresario recibe ordinariamente…", "options": ["Conclusiones de aptitud y necesidad de medidas preventivas", "La historia clínica completa", "Todos los diagnósticos sin consentimiento", "Ninguna conclusión sobre el puesto"], "correct": 0, "explanation": "El acceso a información médica personal está limitado por confidencialidad."}, {"id": "prl-q39", "block": "salud", "page": "rd:a37", "ref": "RSP · art. 37", "q": "Después de una ausencia prolongada por motivos de salud, el RSP contempla…", "options": ["Excluir toda evaluación hasta el año siguiente", "Una evaluación de salud para detectar posibles orígenes profesionales y recomendar protección", "Solo formación administrativa", "Una sanción automática"], "correct": 1, "explanation": "El art. 37.3.b incluye ese supuesto junto a evaluación inicial y vigilancia periódica."}, {"id": "prl-q40", "block": "documentacion", "page": "ley:a23", "ref": "LPRL · art. 23", "q": "La relación del art. 23.1.e incluye daños con incapacidad…", "options": ["Solo superior a 15 días", "De cualquier duración, como literal de esa letra", "Superior a un día de trabajo", "Igual o superior a un mes"], "correct": 2, "explanation": "Es el umbral específico de esa relación; no elimina los deberes de notificación de daños."}, {"id": "prl-q41", "block": "documentacion", "page": "ley:a24", "ref": "LPRL · art. 24", "q": "El empresario titular del centro debe…", "options": ["Asumir siempre todos los contratos de las otras empresas", "Sustituir sus evaluaciones sin coordinación", "Limitarse a permitir el acceso", "Informar e instruir sobre riesgos, medidas y emergencias del centro"], "correct": 3, "explanation": "El art. 24.2 establece ese deber hacia los empresarios que desarrollan actividades en el centro."}, {"id": "prl-q42", "block": "documentacion", "page": "ley:a24", "ref": "LPRL · art. 24", "q": "La vigilancia del empresario principal del art. 24.3 se refiere a…", "options": ["Contratas de su propia actividad en sus propios centros", "Cualquier proveedor en cualquier lugar", "Solo empresas sin asalariados", "Solo trabajos administrativos"], "correct": 0, "explanation": "Conserva ambas condiciones para no ampliar indebidamente la regla."}, {"id": "prl-q43", "block": "proteccion", "page": "ley:a26", "ref": "LPRL · art. 26", "q": "La secuencia protectora de la maternidad es…", "options": ["Permiso sin sueldo como primera medida", "Adaptación, cambio compatible y, si procede, suspensión por riesgo", "Suspensión automática, formación y cambio", "Cambio y despido si no hay vacante"], "correct": 1, "explanation": "Los pasos y sus requisitos se regulan en los apartados 1 a 3 del art. 26."}, {"id": "prl-q44", "block": "proteccion", "page": "ley:a27", "ref": "LPRL · art. 27", "q": "La evaluación especial de menores se refiere a quienes tienen…", "options": ["Menos de 21", "Menos de 25", "Menos de 18 años", "Menos de 16 exclusivamente"], "correct": 2, "explanation": "Se realiza antes de incorporarse y ante modificaciones importantes de sus condiciones."}, {"id": "prl-q45", "block": "proteccion", "page": "ley:a28", "ref": "LPRL · art. 28", "q": "En una ETT, formación y vigilancia de la salud corresponden a…", "options": ["La usuaria en exclusiva en todos los casos", "El trabajador por su cuenta", "La ITSS como prestadora", "La empresa de trabajo temporal"], "correct": 3, "explanation": "La usuaria es responsable de las condiciones de ejecución; el artículo distribuye las obligaciones."}, {"id": "prl-q46", "block": "obligaciones", "page": "ley:a29", "ref": "LPRL · art. 29", "q": "Ante una situación que razonablemente entrañe riesgo, el trabajador informa…", "options": ["De inmediato a los destinatarios previstos en el art. 29", "Solo al acabar el turno", "En 15 días", "Solo después de sufrir un daño"], "correct": 0, "explanation": "Los destinatarios son el superior directo y los trabajadores designados o, en su caso, el servicio de prevención."}, {"id": "prl-q47", "block": "obligaciones", "page": "ley:a29", "ref": "LPRL · art. 29", "q": "Los dispositivos de seguridad deben…", "options": ["Utilizarse solo durante inspecciones", "Utilizarse correctamente y no ponerse fuera de funcionamiento", "Anularse si ralentizan el trabajo", "Desconectarse a criterio del usuario sin instrucciones"], "correct": 1, "explanation": "Es un deber expreso del art. 29.2.3.º."}, {"id": "prl-q48", "block": "obligaciones", "page": "ley:a29", "ref": "LPRL · art. 29", "q": "El incumplimiento preventivo de un funcionario puede ser…", "options": ["Siempre una infracción de tráfico", "Una conducta sin consecuencias", "Falta conforme a su régimen disciplinario", "Siempre delito automáticamente"], "correct": 2, "explanation": "El art. 29.3 remite al régimen disciplinario aplicable, sin establecer delito automático."}, {"id": "prl-q49", "block": "modalidades", "page": "rd:a11", "ref": "RSP · art. 11", "q": "Un empresario con 25 trabajadores puede asumir personalmente la prevención si…", "options": ["Tiene varios centros y actividad del anexo I", "Asume también todos los reconocimientos médicos", "Lo decide sin formación ni presencia habitual", "Hay único centro y cumple el resto de requisitos, excluida vigilancia de salud"], "correct": 3, "explanation": "Se exigen simultáneamente plantilla, centro único en ese tramo, actividad no anexo I, presencia y capacidad."}, {"id": "prl-q50", "block": "modalidades", "page": "rd:a11", "ref": "RSP · art. 11", "q": "La asunción personal por el empresario excluye siempre…", "options": ["Las actividades de vigilancia de la salud", "La información de riesgos", "Todas las evaluaciones elementales", "La planificación de cualquier medida"], "correct": 0, "explanation": "Deben cubrirse por otra modalidad preventiva."}, {"id": "prl-q51", "block": "modalidades", "page": "rd:a13", "ref": "RSP · art. 13", "q": "Los trabajadores designados deben contar con…", "options": ["Facultad para trasladar el coste a la plantilla", "Capacidad, tiempo, medios y número suficiente", "Solo un nombramiento escrito sin recursos", "Exclusivamente formación sanitaria"], "correct": 1, "explanation": "La adecuación depende del tamaño, riesgos y distribución de la empresa."}, {"id": "prl-q52", "block": "propio", "page": "rd:a14", "ref": "RSP · art. 14", "q": "El umbral general que obliga a servicio propio por tamaño es…", "options": ["Más de 250 en toda actividad", "50 o más", "Más de 500 trabajadores", "500 o más en todos los casos"], "correct": 2, "explanation": "La letra a usa más de 500; la letra b abarca 250–500 con actividades del anexo I."}, {"id": "prl-q53", "block": "propio", "page": "rd:a14", "ref": "RSP · art. 14", "q": "Una empresa de 250 trabajadores con actividad del anexo I debe…", "options": ["Asumir personalmente la prevención", "Constituir solo un comité y nada más", "Esperar a superar 500", "Constituir servicio de prevención propio"], "correct": 3, "explanation": "El tramo de 250 a 500 incluye sus extremos."}, {"id": "prl-q54", "block": "propio", "page": "rd:a15", "ref": "RSP · art. 15", "q": "El servicio propio contará al menos con…", "options": ["Dos especialidades o disciplinas preventivas", "Una disciplina", "Tres en todo caso", "Cuatro obligatoriamente como mínimo de SPP"], "correct": 0, "explanation": "El art. 15 fija dos; no lo confundas con mancomunados o ajenos."}, {"id": "prl-q55", "block": "ajeno", "page": "rd:a21", "ref": "RSP · art. 21", "q": "El servicio mancomunado tiene consideración de…", "options": ["Comité de Seguridad y Salud", "Servicio propio de las empresas participantes", "Servicio ajeno en todos los casos", "Órgano de la autoridad laboral"], "correct": 1, "explanation": "Debe contar al menos con tres disciplinas preventivas."}, {"id": "prl-q56", "block": "ajeno", "page": "rd:a18", "ref": "RSP · art. 18", "q": "Un servicio de prevención ajeno debe contar con…", "options": ["Solo medicina del trabajo", "Solo tres sin vigilancia de salud", "Las cuatro especialidades o disciplinas preventivas", "Solo dos a su elección"], "correct": 2, "explanation": "El mínimo de dos es del SPP y el de tres del mancomunado."}, {"id": "prl-q57", "block": "ajeno", "page": "rd:a25", "ref": "RSP · art. 25", "q": "El silencio en la solicitud de acreditación como SPA es…", "options": ["Estimatorio siempre", "Una acreditación provisional automática", "La autorización sanitaria automática", "Desestimatorio"], "correct": 3, "explanation": "El plazo ordinario es tres meses, ampliado a seis en el supuesto del art. 25.3."}, {"id": "prl-q58", "block": "recursos", "page": "ley:a32bis", "ref": "LPRL · art. 32 bis", "q": "¿Qué puede exigir la presencia de recursos preventivos?", "options": ["Un requerimiento de la ITSS por las condiciones detectadas", "Solo superar 500 trabajadores", "La mera existencia de un comité", "Solo una petición del fabricante"], "correct": 0, "explanation": "Es uno de los tres supuestos del art. 32 bis.1."}, {"id": "prl-q59", "block": "recursos", "page": "ley:a32bis", "ref": "LPRL · art. 32 bis", "q": "Otro trabajador asignado expresamente a presencia preventiva necesita, como mínimo…", "options": ["Ser delegado sindical", "Formación de nivel básico, además de conocimientos, cualificación y experiencia necesarios", "Solo experiencia sin formación", "Siempre nivel superior en las cuatro disciplinas"], "correct": 1, "explanation": "El art. 32 bis.4 exige ese conjunto de condiciones."}, {"id": "prl-q60", "block": "recursos", "page": "rd:a22bis", "ref": "RSP · art. 22 bis", "q": "La presencia del recurso preventivo es una medida…", "options": ["Que elimina la necesidad de evaluación", "Que transfiere el deber empresarial al recurso", "Complementaria a las restantes medidas preventivas", "Sustitutiva de la protección colectiva"], "correct": 2, "explanation": "Su finalidad es vigilar cumplimiento y eficacia mientras se mantiene la situación."}, {"id": "prl-q61", "block": "consulta", "page": "ley:a33", "ref": "LPRL · art. 33", "q": "Las decisiones preventivas del art. 33 se consultan…", "options": ["Solo después de ejecutarlas", "Solo cada cuatro años", "Únicamente si existe un accidente", "Con la debida antelación"], "correct": 3, "explanation": "La consulta debe permitir participación efectiva antes de la decisión."}, {"id": "prl-q62", "block": "consulta", "page": "ley:a34", "ref": "LPRL · art. 34", "q": "El cauce representativo del art. 34 se prevé en empresas con…", "options": ["Seis o más trabajadores", "Más de 50", "Más de 500", "Exactamente 25"], "correct": 0, "explanation": "No se debe confundir ese umbral con el del Comité de Seguridad y Salud."}, {"id": "prl-q63", "block": "consulta", "page": "ley:a33", "ref": "LPRL · art. 33", "q": "La designación de trabajadores para medidas de emergencia…", "options": ["Exige siempre referéndum vinculante", "Está incluida entre las cuestiones objeto de consulta", "No puede consultarse", "Solo se consulta a la mutua"], "correct": 1, "explanation": "El art. 33.1.c la incluye expresamente."}, {"id": "prl-q64", "block": "delegados", "page": "ley:a35", "ref": "LPRL · art. 35", "q": "A una empresa con exactamente 100 trabajadores le corresponden, según escala general…", "options": ["3", "4", "2 delegados de prevención", "1"], "correct": 2, "explanation": "El primer tramo es 50–100; 101 abre el tramo de tres."}, {"id": "prl-q65", "block": "delegados", "page": "ley:a35", "ref": "LPRL · art. 35", "q": "Con exactamente 500 trabajadores, la escala general establece…", "options": ["2", "4", "5", "3 delegados de prevención"], "correct": 3, "explanation": "500 cierra el tramo 101–500; a partir de 501 son cuatro."}, {"id": "prl-q66", "block": "delegados", "page": "ley:a35", "ref": "LPRL · art. 35", "q": "En contratos de hasta un año, cada 200 días trabajados o fracción computa como…", "options": ["Un trabajador más", "Dos trabajadores", "Medio trabajador", "Un delegado de prevención"], "correct": 0, "explanation": "Se cuentan los días del año anterior a la designación, no solo el día de la elección."}, {"id": "prl-q67", "block": "facultades", "page": "ley:a36", "ref": "LPRL · art. 36", "q": "El plazo ordinario para los informes de consulta de delegados es…", "options": ["Un mes", "15 días", "24 horas", "3 días hábiles"], "correct": 1, "explanation": "Para medidas contra riesgos inminentes se reduce al tiempo imprescindible."}, {"id": "prl-q68", "block": "facultades", "page": "ley:a36", "ref": "LPRL · art. 36", "q": "La negativa empresarial a adoptar medidas propuestas por el delegado debe ser…", "options": ["Aprobada por unanimidad del comité", "Automáticamente sancionada por el delegado", "Motivada", "Siempre verbal"], "correct": 2, "explanation": "El art. 36.4 exige motivación."}, {"id": "prl-q69", "block": "facultades", "page": "ley:a37", "ref": "LPRL · art. 37", "q": "Las reuniones del Comité de Seguridad y Salud son…", "options": ["Tiempo personal sin compensación", "Siempre consumo de crédito horario", "Formación voluntaria", "Trabajo efectivo sin imputación al crédito horario"], "correct": 3, "explanation": "El art. 37.1 establece expresamente esa excepción al crédito."}, {"id": "prl-q70", "block": "comite", "page": "ley:a38", "ref": "LPRL · art. 38", "q": "El Comité de Seguridad y Salud se constituye con…", "options": ["50 o más trabajadores", "Más de 50 exclusivamente", "Más de 500", "25 o más en todo caso"], "correct": 0, "explanation": "El umbral incluye exactamente 50 y puede referirse a empresa o centro de trabajo."}, {"id": "prl-q71", "block": "comite", "page": "ley:a38", "ref": "LPRL · art. 38", "q": "El comité se reúne ordinariamente…", "options": ["Cada cuatro años", "Trimestralmente", "Mensualmente", "Semestralmente"], "correct": 1, "explanation": "También cuando lo solicite alguna de sus representaciones."}, {"id": "prl-q72", "block": "comite", "page": "ley:a38", "ref": "LPRL · art. 38", "q": "Los técnicos de prevención que no integran el comité participan…", "options": ["Sin voz ni voto", "Solo con autorización judicial", "Con voz y sin voto", "Siempre con voz y voto"], "correct": 2, "explanation": "La misma regla se prevé para delegados sindicales no integrantes en los términos del artículo."}, {"id": "prl-q73", "block": "responsabilidades", "page": "ley:a42", "ref": "LPRL · art. 42", "q": "La responsabilidad administrativa preventiva puede ser compatible con…", "options": ["Solo una amonestación verbal", "Ninguna otra consecuencia en ningún caso", "La eliminación del deber de reparación", "Indemnizaciones y recargo de prestaciones"], "correct": 3, "explanation": "El art. 42.3 declara esa compatibilidad en los términos de la normativa aplicable."}, {"id": "prl-q74", "block": "responsabilidades", "page": "ley:a43", "ref": "LPRL · art. 43", "q": "Un requerimiento de subsanación de la ITSS…", "options": ["No impide la propuesta de sanción correspondiente", "Elimina toda posibilidad de sanción", "Siempre suspende la actividad", "Solo se comunica de palabra"], "correct": 0, "explanation": "El art. 43 exige requerimiento escrito con deficiencias y plazo, sin perjuicio de sanción."}, {"id": "prl-q75", "block": "responsabilidades", "page": "ley:a45", "ref": "LPRL · art. 45", "q": "Los artículos 45–52 de la LPRL están…", "options": ["Sustituidos por decisiones del comité", "Derogados", "Todos vigentes con las cuantías de 1995", "Suspendidos solo durante emergencias"], "correct": 1, "explanation": "La consolidación los identifica como derogados; evita estudiar sus versiones históricas como vigentes."}, {"id": "prl-q76", "block": "auditoria", "page": "rd:a30", "ref": "RSP · art. 30", "q": "La primera auditoría se realiza dentro de los 12 meses siguientes a…", "options": ["La última reunión del comité", "La primera sanción", "Disponer de la planificación de la actividad preventiva", "La contratación del primer trabajador en todo caso"], "correct": 2, "explanation": "El inicio del cómputo se fija en el art. 30.4."}, {"id": "prl-q77", "block": "auditoria", "page": "rd:a30", "ref": "RSP · art. 30", "q": "La repetición ordinaria es cada…", "options": ["2 años en todas las empresas", "12 meses en todos los casos", "5 años, o 3 con anexo I", "4 años, o 2 si hay actividades del anexo I"], "correct": 3, "explanation": "Puede ampliarse la revisión en dos años por acuerdo sobre modalidad con representación especializada."}, {"id": "prl-q78", "block": "auditoria", "page": "rd:a29", "ref": "RSP · art. 29", "q": "La excepción de auditoría de empresas pequeñas exige…", "options": ["Hasta 50, sin anexo I, recursos propios, eficacia evidente y notificación, con posibilidad de requerimiento", "Solo tener menos de 500", "Solo un acuerdo verbal con la plantilla", "Únicamente contratar un EPI adecuado"], "correct": 0, "explanation": "El art. 29.3 recoge requisitos acumulativos; la autoridad puede exigir auditoría según el apartado 4."}, {"id": "prl-q79", "block": "formacion", "page": "rd:a35", "ref": "RSP · art. 35", "q": "La duración mínima del programa básico para actividades del anexo I es…", "options": ["600 horas", "50 horas", "30 horas", "300 horas"], "correct": 1, "explanation": "En las demás empresas la vía formativa básica es de al menos 30 horas."}, {"id": "prl-q80", "block": "formacion", "page": "rd:a36", "ref": "RSP · art. 36", "q": "El programa de nivel intermedio tiene duración no inferior a…", "options": ["50 horas", "600 horas", "300 horas", "30 horas"], "correct": 2, "explanation": "El art. 36 remite al programa del anexo V."}, {"id": "prl-q81", "block": "formacion", "page": "rd:a37", "ref": "RSP · art. 37", "q": "Para funciones de nivel superior, el art. 37.2 exige…", "options": ["Solo 600 horas sin titulación", "Solo experiencia de dos años", "Solo nivel básico y nombramiento", "Titulación universitaria oficial y formación universitaria acreditada de al menos 600 horas"], "correct": 3, "explanation": "Los requisitos sanitarios específicos se añaden para vigilancia y control de la salud."}, {"id": "prl-q82", "block": "anexos", "page": "rd:ani", "ref": "RSP · disposiciones / anexos", "q": "El anexo I incluye exposición a agentes biológicos de los grupos…", "options": ["3 y 4", "1 y 2 exclusivamente", "2 y 3 exclusivamente", "Solo 4"], "correct": 0, "explanation": "El apartado d recoge los grupos 3 y 4."}, {"id": "prl-q83", "block": "anexos", "page": "rd:aniv", "ref": "RSP · disposiciones / anexos", "q": "El programa de formación de nivel básico figura en el anexo…", "options": ["VI", "IV", "II", "V"], "correct": 1, "explanation": "II es notificación sobre auditoría; V intermedio; VI superior."}, {"id": "prl-q84", "block": "anexos", "page": "rd:anviii", "ref": "RSP · disposiciones / anexos", "q": "¿Qué anexos tratan específicamente de embarazo o lactancia?", "options": ["III y IV", "V y VI", "VII y VIII", "I y II"], "correct": 2, "explanation": "El VII recoge posibles influencias negativas; el VIII, agentes y condiciones de no exposición en los términos legales."}];
const sourceLink=(ref,label)=>{const [norm,anchor]=ref.split(":");const base=norm==="ley"?"https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292":"https://www.boe.es/buscar/act.php?id=BOE-A-1997-1853";return `<a href="${base}#${anchor}" target="_blank" rel="noopener noreferrer">${label||((norm==="ley"?"LPRL":"RSP")+" · "+anchor)} ↗</a>`};
const blocks=[...document.querySelectorAll('#study section')];
const state={get(k,f){try{return JSON.parse(localStorage.getItem('prl-'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('prl-'+k,JSON.stringify(v))}catch{}}};
let done=new Set(state.get('blocks-v1',[]));
function progress(){const n=blocks.filter(b=>done.has(b.id)).length;document.querySelector('#progressbar').style.width=(n/blocks.length*100)+'%';const p=document.querySelector('.progress');p.setAttribute('aria-valuemax',blocks.length);p.setAttribute('aria-valuenow',n);document.querySelector('#progresslabel').textContent=`${n} de ${blocks.length} bloques repasados`;document.querySelector('#mobileprogress').textContent=`· ${n}/${blocks.length}`;state.set('blocks-v1',[...done])}
document.querySelector('#index').innerHTML=blocks.map((b,i)=>`<a href="#${b.id}" data-block="${b.id}"><span>${String(i+1).padStart(2,'0')}</span>${b.dataset.title}</a>`).join('');document.querySelector('#mobilelinks').innerHTML=document.querySelector('#index').innerHTML;
blocks.forEach(b=>{const label=document.createElement('label');label.className='done';const c=document.createElement('input');c.type='checkbox';c.checked=done.has(b.id);c.addEventListener('change',()=>{c.checked?done.add(b.id):done.delete(b.id);progress()});label.append(c,document.createTextNode('Puedo explicar este bloque sin mirar'));b.append(label)});progress();
const tabs=[...document.querySelectorAll('[data-view]')];let currentView='study';
function showView(v,scroll=true){currentView=v;document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);tabs.forEach(t=>{const active=t.dataset.view===v;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1});document.querySelector('#studytools').hidden=v!=='study';document.querySelector('.mobileindex').hidden=v!=='study';if(scroll)document.querySelector('main').scrollIntoView({behavior:'auto',block:'start'})}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>showView(t.dataset.view));t.addEventListener('keydown',e=>{let j;if(e.key==='ArrowRight')j=(i+1)%tabs.length;else if(e.key==='ArrowLeft')j=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')j=0;else if(e.key==='End')j=tabs.length-1;if(j!==undefined){e.preventDefault();tabs[j].focus();showView(tabs[j].dataset.view)}})});
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function searchBlocks(){const q=normalize(document.querySelector('#search').value.trim());let n=0;blocks.forEach(b=>{b.hidden=q&&!normalize(b.textContent).includes(q);if(!b.hidden)n++});document.querySelector('#noresults').hidden=n>0;document.querySelector('#resultcount').textContent=q?`${n} ${n===1?'bloque':'bloques'}`:''}
document.querySelector('#search').addEventListener('input',searchBlocks);document.querySelector('#essentials').checked=state.get('essentials',false);document.querySelector('#study').classList.toggle('onlyessential',document.querySelector('#essentials').checked);document.querySelector('#essentials').addEventListener('change',e=>{document.querySelector('#study').classList.toggle('onlyessential',e.target.checked);state.set('essentials',e.target.checked)});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&document.querySelector(a.getAttribute('href'))?.matches('#study section')){showView('study',false);document.querySelector('#search').value='';searchBlocks();document.querySelector('.mobileindex').open=false;document.querySelector(a.getAttribute('href')).scrollIntoView();}});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('#index a').forEach(a=>a.classList.toggle('active',a.dataset.block===e.target.id))})},{rootMargin:'-110px 0px -65% 0px'});blocks.forEach(b=>observer.observe(b));
document.querySelector('#print').addEventListener('click',()=>window.print());
let printSnapshot;
window.addEventListener('beforeprint',()=>{const ds=[...document.querySelectorAll('#study details')];printSnapshot={essential:document.querySelector('#study').classList.contains('onlyessential'),details:ds.map(d=>[d,d.open])};document.querySelector('#study').classList.remove('onlyessential');ds.forEach(d=>d.open=true)});
window.addEventListener('afterprint',()=>{if(!printSnapshot)return;document.querySelector('#study').classList.toggle('onlyessential',printSnapshot.essential);printSnapshot.details.forEach(([d,open])=>d.open=open);printSnapshot=null});
const topicName=id=>blocks.find(b=>b.id===id)?.dataset.title||id;
const optionTopics=blocks.map(b=>`<option value="${b.id}">${b.dataset.title}</option>`).join('');document.querySelector('#cardtopic').insertAdjacentHTML('beforeend',optionTopics);document.querySelector('#quiztopic').insertAdjacentHTML('beforeend',optionTopics);
document.querySelector('#quickgrid').innerHTML=blocks.map((b,i)=>`<div class="quickcard"><div class="overline">${String(i+1).padStart(2,'0')}</div><h3>${b.dataset.title}</h3><p>${b.querySelector('.essential').innerHTML.replace(/<div class="overline">.*?<\/div>/,'')}</p><a href="#${b.id}">Revisar el bloque →</a></div>`).join('');
const storyNodes=[...document.querySelectorAll('#study .story')];document.querySelector('#stories').innerHTML=storyNodes.map(s=>`<div class="story">${s.innerHTML}<a class="note" href="#${s.closest('section').id}">Ver el dato en su contexto →</a></div>`).join('');
function renderPegs(){const q=normalize(document.querySelector('#pegsearch').value.trim());const matches=pegs.map((label,n)=>({label,n})).filter(p=>!q||normalize(p.n+' '+p.label).includes(q));document.querySelector('#peglist').innerHTML=matches.length?matches.map(p=>`<div class="peg"><b>${p.n}</b>${p.label}</div>`).join(''):'<p class="note">No hay casillas con ese término.</p>'}document.querySelector('#pegsearch').addEventListener('input',renderPegs);renderPegs();
let cardState=state.get('cards-v1',{});let deck=[],position=0,revealed=false;
function cardPool(){const type=document.querySelector('#deck').value;const topic=document.querySelector('#cardtopic').value;return flashcards.filter(c=>{const s=cardState[c.id];return(topic==='all'||c.block===topic)&&(type==='all'||(type==='repeat'&&s?.repeat)||(type==='due'&&(!s?.due||s.due<=Date.now())))})}
function renderCard(status=''){revealed=false;const c=deck[position];document.querySelector('#flasha').hidden=true;document.querySelector('#again').disabled=true;document.querySelector('#remember').disabled=true;document.querySelector('#flashstatus').textContent=status;const nDue=flashcards.filter(c=>!cardState[c.id]?.due||cardState[c.id].due<=Date.now()).length;document.querySelector('#flashcount').textContent=c?`Tarjeta ${position+1} de ${deck.length} · ${nDue} pendientes hoy en total`:`Mazo vacío · ${nDue} pendientes hoy en total`;document.querySelector('#flashtag').textContent=c?topicName(c.block)+' · '+c.ref:'Sin tarjetas pendientes';document.querySelector('#flashq').textContent=c?c.q:'Has completado este mazo. Puedes practicar todas las tarjetas o cambiar de bloque.';document.querySelector('#reveal').disabled=!c;document.querySelector('#prev').disabled=!c;document.querySelector('#next').disabled=!c;document.querySelector('#flasha').innerHTML=c?`<p>${c.a}</p><a href="#${c.block}">Revisar el bloque →</a> ${sourceLink(c.page,'Ver fuente')}`:'';}
function rebuildDeck(){deck=cardPool();position=0;renderCard()}
document.querySelector('#deck').onchange=rebuildDeck;document.querySelector('#cardtopic').onchange=rebuildDeck;document.querySelector('#shuffle').onclick=()=>{deck=cardPool();for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}position=0;renderCard()};
function revealCard(){if(!deck.length)return;revealed=true;document.querySelector('#flasha').hidden=false;document.querySelector('#again').disabled=false;document.querySelector('#remember').disabled=false;document.querySelector('#reveal').hidden=true;document.querySelector('#flasha').focus()}
const originalRenderCard=renderCard;renderCard=function(status=''){document.querySelector('#reveal').hidden=false;originalRenderCard(status)};
document.querySelector('#reveal').onclick=revealCard;
function moveCard(delta){if(!deck.length)return;position=(position+delta+deck.length)%deck.length;renderCard()}document.querySelector('#prev').onclick=()=>moveCard(-1);document.querySelector('#next').onclick=()=>moveCard(1);
function gradeCard(remember){if(!revealed||!deck.length)return;const c=deck[position];const previous=cardState[c.id]||{};let label;if(remember){const level=Math.min((previous.level||0)+1,4);const days=[1,3,7,14][level-1];const due=Date.now()+days*86400000;cardState[c.id]={level,due,repeat:false};label=`Guardada. Próximo repaso: ${new Intl.DateTimeFormat('es-ES',{timeZone:'Europe/Madrid',day:'numeric',month:'long'}).format(due)} (en ${days} ${days===1?'día':'días'}).`}else{cardState[c.id]={level:0,due:Date.now(),repeat:true};label='Guardada para repetir hoy. También está en el mazo «Para repetir».'}state.set('cards-v1',cardState);const oldPos=position;const nextPool=cardPool();const ids=new Set(nextPool.map(x=>x.id));deck=deck.filter(x=>ids.has(x.id));const idx=deck.findIndex(x=>x.id===c.id);position=idx>=0?(idx+1)%deck.length:Math.min(oldPos,Math.max(deck.length-1,0));renderCard(label)}document.querySelector('#again').onclick=()=>gradeCard(false);document.querySelector('#remember').onclick=()=>gradeCard(true);rebuildDeck();
document.addEventListener('keydown',e=>{if(currentView!=='flash'||e.target.matches('input,select,textarea,button,a'))return;if(e.key===' '){e.preventDefault();if(!revealed)revealCard()}if(e.key==='ArrowRight'){e.preventDefault();moveCard(1)}if(e.key==='ArrowLeft'){e.preventDefault();moveCard(-1)}});
let quizAnswers={};
const quizEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function quizPool(){const topic=document.querySelector('#quiztopic').value;return quizdata.map((q,i)=>({q,i})).filter(({q})=>(topic==='all'||q.block===topic))}
function updateScore(){const visible=quizPool();const answered=visible.filter(x=>Object.hasOwn(quizAnswers,x.i));const correct=answered.filter(x=>quizAnswers[x.i]===x.q.correct);document.querySelector('#score').textContent=`${correct.length} ${correct.length===1?'acierto':'aciertos'} · ${answered.length}/${visible.length} respondidas`}
function renderQuiz(){const visible=quizPool();document.querySelector('#quizlist').innerHTML=visible.length?visible.map(({q,i})=>`<article class="quizitem" data-question="${i}"${q.id?` id="quiz-${quizEscape(q.id)}"`:''}><div class="quizmeta"><div class="overline">${q.origin==='academia'?quizEscape(q.sourceLabel)+' · '+q.sourceNumber:'Cuaderno · '+(i+1)} · ${quizEscape(topicName(q.block))}</div>${q.review?'<span class="quizbadge">Con aclaración en la corrección</span>':''}</div><h3>${quizEscape(q.q)}</h3><div class="options">${q.options.map((o,j)=>`<button data-answer="${j}"><span aria-hidden="true">${String.fromCharCode(65+j)} · </span>${quizEscape(o)}</button>`).join('')}</div><div class="feedback" hidden role="status"></div></article>`).join(''):'<p class="empty" role="status">Este test no contiene preguntas de ese bloque. Cambia el test o selecciona «Todo el tema».</p>';Object.entries(quizAnswers).forEach(([i,answer])=>displayAnswer(Number(i),answer));updateScore()}
function displayAnswer(i,answer){const row=document.querySelector(`[data-question="${i}"]`);if(!row)return;const q=quizdata[i];const correct=answer===q.correct;row.querySelectorAll('[data-answer]').forEach(b=>{const n=Number(b.dataset.answer);b.disabled=true;b.classList.toggle('correct',n===q.correct);b.classList.toggle('wrong',n===answer&&!correct);b.setAttribute('aria-label',q.options[n]+(n===q.correct?' · Respuesta correcta':n===answer?' · Tu respuesta incorrecta':''))});const feedback=row.querySelector('.feedback');feedback.hidden=false;feedback.classList.toggle('error',!correct);const pageLinks=[...new Set([q.page,...(q.extraPages||[])])].filter(p=>typeof p==="string"&&/^(ley|rd):[a-z0-9-]+$/.test(p)).map(p=>sourceLink(p)).join('');const review=q.review?`<details class="quizreview"><summary>${quizEscape(q.review.title)}</summary><p>${quizEscape(q.review.text)}</p>${q.review.links?.length?`<ul>${q.review.links.map(link=>`<li><a href="${quizEscape(link.url)}" target="_blank" rel="noopener noreferrer">${quizEscape(link.title)} ↗</a></li>`).join('')}</ul>`:''}</details>`:'';feedback.innerHTML=`<p><b>${correct?'Correcto.':'Revisa: '+quizEscape(q.options[q.correct])+'.'}</b> ${quizEscape(q.explanation)}</p>${q.contrast?`<p><b>Para distinguirlo.</b> ${quizEscape(q.contrast)}</p>`:''}${review}<div class="quizlinks"><a href="#${q.block}">${q.origin==='academia'?'Revisar bloque relacionado':'Volver al bloque'} →</a>${pageLinks?'<span>Consultar BOE:</span>'+pageLinks:'<span>Clave procedente del test compartido.</span>'}</div>`}
document.querySelector('#quizlist').addEventListener('click',e=>{const button=e.target.closest('[data-answer]');if(!button)return;const i=Number(button.closest('[data-question]').dataset.question);if(Object.hasOwn(quizAnswers,i))return;quizAnswers[i]=Number(button.dataset.answer);displayAnswer(i,quizAnswers[i]);updateScore()});document.querySelector('#quiztopic').onchange=renderQuiz;document.querySelector('#resetquiz').onclick=()=>{quizPool().forEach(({i})=>delete quizAnswers[i]);renderQuiz()};renderQuiz();
function openHash(){const id=location.hash.slice(1);if(['quick','flash','quiz','images','memory'].includes(id))showView(id,false);else if(blocks.some(b=>b.id===id)){showView('study',false);document.querySelector('#search').value='';searchBlocks();document.querySelector('.mobileindex').open=false;requestAnimationFrame(()=>document.getElementById(id).scrollIntoView())}}window.addEventListener('hashchange',openHash);openHash();
